  <script>
    const form = document.getElementById('paymentForm');
    const phoneInput = document.getElementById('phoneNumber');
    const phoneError = document.getElementById('phoneError');
    const payButton = document.getElementById('payButton');
    const toast = document.getElementById('toast');
    const backButton = document.getElementById('backButton');

    function toWesternDigits(value) {
      return value
        .replace(/[٠-٩]/g, digit => String(digit.charCodeAt(0) - 0x0660))
        .replace(/[۰-۹]/g, digit => String(digit.charCodeAt(0) - 0x06F0));
    }

    function normalizePhone(value) {
      return toWesternDigits(value).replace(/[^\d+]/g, '');
    }

    function isValidUaePhone(value) {
      const phone = normalizePhone(value);
      return /^(?:\+971|00971|971)?0?5[0-9]{8}$/.test(phone);
    }

    phoneInput.addEventListener('input', () => {
      phoneError.textContent = '';
      const position = phoneInput.selectionStart;
      phoneInput.value = toWesternDigits(phoneInput.value);
      if (position !== null) {
        phoneInput.setSelectionRange(position, position);
      }
    });

    form.addEventListener('submit', event => {
      event.preventDefault();

      if (!isValidUaePhone(phoneInput.value)) {
        phoneError.textContent = 'أدخل رقم هاتف إماراتي صحيحًا، مثل 050 123 4567.';
        phoneInput.focus();
        return;
      }

      phoneError.textContent = '';
      payButton.disabled = true;
      payButton.textContent = 'جارٍ تنفيذ الدفع…';

      setTimeout(() => {
        payButton.disabled = false;
        payButton.textContent = 'ادفع الآن';
        toast.textContent = 'تم تنفيذ الدفع بنجاح، وسيصلك الإيصال عبر رسالة نصية.';
        toast.classList.add('show');

        setTimeout(() => toast.classList.remove('show'), 3500);
      }, 900);
    });

    backButton.addEventListener('click', () => {
      if (history.length > 1) {
        history.back();
      } else {
        toast.textContent = 'لا توجد صفحة سابقة.';
        toast.classList.add('show');
        setTimeout(() => toast.classList.remove('show'), 2500);
      }
    });
  </script>
